// SPDX-License-Identifier: MIT
pragma solidity ^0.8.0;

struct OracleAttestationData {
    bytes32 queryId;
    ReportData report;
    uint256 attestationTimestamp; //timestamp of validatorSignatures on report
}

struct ReportData {
    bytes value;
    uint256 timestamp; //timestamp of reporter signature aggregation
    uint256 aggregatePower;
    uint256 previousTimestamp;
    uint256 nextTimestamp;
    uint256 lastConsensusTimestamp;
}

struct Signature {
    uint8 v;
    bytes32 r;
    bytes32 s;
}

struct Validator {
    address addr;
    uint256 power;
}

interface ITellorDataBridge {
    function guardian() external view returns (address);
    function powerThreshold() external view returns (uint256);
    function unbondingPeriod() external view returns (uint256);
    function validatorTimestamp() external view returns (uint256);
    function verifyOracleData(
        OracleAttestationData calldata _attestData,
        Validator[] calldata _currentValidatorSet,
        Signature[] calldata _sigs
    ) external view;
}

contracts/interfaces/ITellorShepherd.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.19;

/// @notice Consumer-facing interface for a view-first Tellor price oracle.
interface ITellorShepherd {
    enum Status {
        UNAVAILABLE,
        NORMAL,
        RECOVERY,
        PAUSED,
        INVALID_PRICE,
        INVALID_COVERAGE,
        DEVIATING
    }

    struct PricePreview {
        Status status;
        uint256 candidateIndex;
        uint256 candidateValue;
        uint256 candidateAggregateTimestamp;
        uint256 candidateRelayTimestamp;
        uint256 twap;
        uint256 deviationBps;
        uint256 twapStartTimestamp;
        uint256 twapEndTimestamp;
        uint256 observationCount;
    }

    /// @notice Returns the current validated price or the latched recovery snapshot.
    /// @return value SpotPrice with 18 decimals.
    /// @return aggregateTimestamp Tellor aggregate timestamp in milliseconds.
    function getCurrentValue()
        external
        view
        returns (uint256 value, uint256 aggregateTimestamp);

    /// @notice Describes what `getCurrentValue` would return and why it may be unavailable.
    function previewValue() external view returns (PricePreview memory preview);
}

